import { isFunction } from '../../../../utils/validation/isFunction.js';
import { isObject } from '../../../../utils/validation/isObject.js';
export const getDefaultsDTO = (schema) => {
    const defaultsDTO = {};
    for (const mode of ['keyDefault', 'putDefault', 'updateDefault']) {
        const modeDefault = schema.props[mode];
        if (modeDefault === undefined) {
            continue;
        }
        defaultsDTO[mode] = isFunction(modeDefault)
            ? { defaulterId: 'custom' }
            : { defaulterId: 'value', value: modeDefault };
    }
    return defaultsDTO;
};
export const isTransformerWithDTO = (transformer) => isObject(transformer) && 'transformerId' in transformer && 'toJSON' in transformer;
